const head = tokens[0]?.replace(/^["']|["']$/g, "");
if (!head || !GIT_TOKEN_RE.test(head)) return false;
for (let i = 1; i < tokens.length; i++) {
  const t = tokens[i].replace(/^["']|["']$/g, "");
  if (GIT_OPTS_WITH_ARG.has(t)) {
    i++; // 跳过带参选项的参数
    continue;
  }
  // 与 forGitSub 同口径跳过粘连的 -Cdir/-ck=v，否则 git -Cdir commit 整体漏判
  if (/^-[Cc]\S/.test(t) || GIT_OPTS_FLAG_ONLY.has(t) || /^--[\w-]+=/.test(t)) continue;
  return t === "commit";
}

// stripQuoted 用占位 token 替换引号内容（而非空格）：
// 保持 "-C <引号参数>" 的单 token 消耗语义，避免引号形态下 add 被当作 -C 参数吞掉
const stripQuoted = (cmd) => String(cmd).replace(/"[^"]*"|'[^']*'/g, "0");
